-- Match the unselected ball in the preview without storing another bitmap.
local ball=assert(icons['poke-ball']);local muted={}
for k,v in pairs(ball) do muted[k]=v end
muted.palette={}
for i,c in ipairs(ball.palette) do
 local luminance=math.floor((c[1]*299+c[2]*587+c[3]*114)/1000+.5)
 local grey=math.floor(luminance*.74+.5);muted.palette[i]={grey,grey,grey,c[4]}
end
icons['ball-muted']=muted
return icons
